function compass(d){if(d==null)return'–';return ['N','NO','O','SO','S','SW','W','NW'][Math.round(d/45)%8]}
function angleDiff(a,b){let d=Math.abs(a-b)%360;return Math.min(d,360-d)}
function exposure(s,d){if(d==null)return'–';const x=angleDiff(s.facing,d);return x<=35?'auflandig':x<=80?'schräg auflandig':x<=120?'seitlich':'ablandig'}
async function json(url){const r=await fetch(url);if(!r.ok)throw Error('HTTP '+r.status);return r.json()}
function openSheet(html){cancelModes(false);$('#sheetBody').innerHTML=html;$('#sheet').classList.remove('hidden')}
