function googleNav(lat,lon){window.open(`https://www.google.com/maps/dir/?api=1&destination=${lat},${lon}`,'_blank')}
function scoreDetailed(w,m,s,currentCtx=null){let n=28+s.rating*5,reasons=[];if(w?.wind_speed_10m>=8&&w.wind_speed_10m<=26){n+=10;reasons.push('brauchbarer Wind')}if(w?.wind_direction_10m!=null){let d=angleDiff(s.facing,w.wind_direction_10m);if(d<=75){n+=9;reasons.push('Wind zur Küste passend')}else if(d>150)n-=7}if(m?.wave_height>=.2&&m.wave_height<=1.05){n+=10;reasons.push('passende Welle')}if(m?.sea_surface_temperature>=4&&m.sea_surface_temperature<=14){n+=8;reasons.push('passende Wassertemperatur')}let cv=currentCtx?.v??m?.ocean_current_velocity,cd=currentCtx?.dir??m?.ocean_current_direction;if(cv!=null){if(cv>=.12&&cv<=.65){n+=13;reasons.push('leichte–mäßige Strömung')}else if(cv>.65&&cv<=.9){n+=7;reasons.push('deutliche Strömung')}else if(cv<.05)n-=4;if(cd!=null){let rel=angleDiff(s.facing,cd);if(rel>=50&&rel<=130){n+=9;reasons.push('Strömung längs/schräg zur Küste')}else if(rel>145)n+=3}if(currentCtx?.edge>=.06){n+=12;reasons.push('Strömungskante im Umfeld')}}return{score:Math.max(0,Math.min(100,Math.round(n))),reasons}}
function score(w,m,s){return scoreDetailed(w,m,s).score}
async function live(s,forecast=false){let h=forecast?'&hourly=wind_speed_10m,wind_direction_10m,wind_gusts_10m&forecast_hours=48':'';let mh=forecast?'&hourly=wave_height,wave_direction,sea_surface_temperature,ocean_current_velocity,ocean_current_direction,sea_level_height_msl&forecast_hours=48':'';let wu=`https://api.open-meteo.com/v1/forecast?latitude=${s.lat}&longitude=${s.lon}&current=wind_speed_10m,wind_direction_10m,wind_gusts_10m&wind_speed_unit=kmh&timezone=auto${h}`;let mu=`https://marine-api.open-meteo.com/v1/marine?latitude=${s.lat}&longitude=${s.lon}&current=wave_height,wave_direction,sea_surface_temperature,ocean_current_velocity,ocean_current_direction,sea_level_height_msl&velocity_unit=kn&timezone=auto&cell_selection=sea${mh}`;let [w,m]=await Promise.allSettled([json(wu),json(mu)]);return{w:w.value||null,m:m.value||null}}
function seasonActive(){let m=new Date().getMonth()+1;return m>=9||m===1}
function destination(lat,lon,bearing,meters){let R=6371000,b=bearing*Math.PI/180,p1=lat*Math.PI/180,l1=lon*Math.PI/180,d=meters/R;let p2=Math.asin(Math.sin(p1)*Math.cos(d)+Math.cos(p1)*Math.sin(d)*Math.cos(b));let l2=l1+Math.atan2(Math.sin(b)*Math.sin(d)*Math.cos(p1),Math.cos(d)-Math.sin(p1)*Math.sin(p2));return[p2*180/Math.PI,l2*180/Math.PI]}
function bearing(a,b){let p1=a[0]*Math.PI/180,p2=b[0]*Math.PI/180,dl=(b[1]-a[1])*Math.PI/180;let y=Math.sin(dl)*Math.cos(p2),x=Math.cos(p1)*Math.sin(p2)-Math.sin(p1)*Math.cos(p2)*Math.cos(dl);return(Math.atan2(y,x)*180/Math.PI+360)%360}
function seaBearing(s){let c=s.lat>57.84&&s.lon>18.95?[57.94,19.18]:[57.48,18.48];return bearing(c,[s.lat,s.lon])}
function satCenters(s){let b=seaBearing(s);return [destination(s.lat,s.lon,b,320),destination(s.lat,s.lon,b,145),destination(s.lat,s.lon,b,65)];}
function spotIcon(s){return L.divIcon({className:'numberedSpot',html:`<span>${s.id}</span>`,iconSize:[30,30],iconAnchor:[15,15]})}
function customIcon(i){return L.divIcon({className:'customSpotIcon',html:`<span>E${i+1}</span>`,iconSize:[34,34],iconAnchor:[17,17]})}

async function openSpot(s,isCustom=false){selectedSpot=s;map.setView([s.lat,s.lon],14);let title=isCustom?`E${customSpots.indexOf(s)+1} · ${s.name}`:`${s.id} · ${s.name}`;openSheet(`<h2>${favs.has(s.id)?'★ ':''}${title}</h2><div class="subtle">${isCustom?(s.note||'Eigener Spot'):`${'★'.repeat(s.rating)} · ${s.structure} · Küste ${compass(s.facing)}`}</div><div id="spotLive" class="metricGrid"><div class="metric"><small>Live-Daten</small><b>lädt…</b></div></div><div class="actions">${!isCustom?`<button id="favA" class="actionBtn">${favs.has(s.id)?'★ Favorit':'☆ Favorit'}</button>`:''}<button id="parkA" class="actionBtn primary">🅿 Parkplatz</button><button id="navA" class="actionBtn">↗ Spot navigieren</button>${isCustom?'<button id="ce" class="actionBtn">✎ Bearbeiten</button><button id="cd" class="actionBtn danger">Löschen</button>':''}</div>${s.protected?`<div class="officialBox">⚠ ${seasonActive()?'Schutzzeit aktiv. ':''}Nähe eines geschützten Gewässers (${s.protected}). Maßgeblich ist die amtliche Schutzfläche. <a href="${RULES}" target="_blank">Offizielle Regeln</a></div>`:''}<h3>Satellitenansicht</h3><div class="subtle">Die Bildausschnitte sind bewusst seewärts versetzt, damit Küstenlinie und Flachwasser sichtbar bleiben.</div><div class="satGrid"><div><div id="sat1" class="satMap"></div><div class="satCap">Übersicht</div></div><div><div id="sat2" class="satMap"></div><div class="satCap">Küste</div></div><div><div id="sat3" class="satMap"></div><div class="satCap">Detail</div></div></div><div id="parkResults"></div>`);
 if(!isCustom)$('#favA').onclick=()=>{favs.has(s.id)?favs.delete(s.id):favs.add(s.id);localStorage.setItem('gst-favs',JSON.stringify([...favs]));openSpot(s);renderList()};$('#navA').onclick=()=>googleNav(s.lat,s.lon);$('#parkA').onclick=()=>loadParkingNear(s,true);
 if(isCustom){$('#ce').onclick=()=>editCustom(s);$('#cd').onclick=()=>{if(confirm('Spot löschen?')){customSpots=customSpots.filter(x=>x.id!==s.id);saveCustom();renderCustom();closeSheet()}}}
 let centers=satCenters(s);[13,15,17].forEach((z,i)=>setTimeout(()=>{let mm=L.map('sat'+(i+1),{zoomControl:false,attributionControl:false,scrollWheelZoom:false}).setView(centers[i],z);L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:19}).addTo(mm);L.circleMarker([s.lat,s.lon],{radius:4,weight:1,fillOpacity:.8}).addTo(mm)},50));
 try{let r=await live(s,true),w=r.w?.current,m=r.m?.current,sc=score(w,m,{rating:s.rating||3,facing:s.facing||270});$('#spotLive').innerHTML=`<div class="metric"><small>Score</small><b>${sc}/100</b></div><div class="metric"><small>Wind</small><b>${w?.wind_speed_10m??'–'} km/h</b><small>${compass(w?.wind_direction_10m)} · ${exposure({facing:s.facing||270},w?.wind_direction_10m)}</small></div><div class="metric"><small>Welle</small><b>${m?.wave_height??'–'} m</b><small>${compass(m?.wave_direction)}</small></div><div class="metric"><small>Wasser</small><b>${m?.sea_surface_temperature??'–'} °C</b><small>Strömung ${m?.ocean_current_velocity??'–'} kn ${compass(m?.ocean_current_direction)}</small></div>`}catch{$('#spotLive').innerHTML='<div class="warnBox">Live-Daten derzeit nicht verfügbar.</div>'}}

function renderSpots(){spotLayer.clearLayers();spots.forEach(s=>L.marker([s.lat,s.lon],{title:`${s.id} ${s.name}`,icon:spotIcon(s)}).on('click',()=>openSpot(s)).addTo(spotLayer))}renderSpots();
function renderList(){let b=$('#spotList');b.innerHTML=`<div class="spotFilter"><button data-mode="all" class="${spotListMode==='all'?'active':''}">Alle</button><button data-mode="built" class="${spotListMode==='built'?'active':''}">Spots</button><button data-mode="own" class="${spotListMode==='own'?'active':''}">Eigene</button></div>`;let addBuilt=spotListMode!=='own',addOwn=spotListMode!=='built';if(addBuilt)spots.forEach(s=>{let d=document.createElement('div');d.className='spotCard';d.innerHTML=`<h3><span class="listNo">${s.id}</span>${favs.has(s.id)?'★ ':''}${s.name}</h3><p>${s.structure}</p><span class="badge">Küste ${compass(s.facing)}</span>`;d.onclick=()=>openSpot(s);b.appendChild(d)});if(addOwn)customSpots.forEach((s,i)=>{let d=document.createElement('div');d.className='spotCard ownCard';d.innerHTML=`<h3><span class="listNo ownNo">E${i+1}</span>${s.name}</h3><p>${s.note||'Eigener Spot'}</p><span class="badge">Eigener Spot</span>`;d.onclick=()=>openSpot(s,true);b.appendChild(d)});b.querySelectorAll('.spotFilter button').forEach(x=>x.onclick=()=>{spotListMode=x.dataset.mode;renderList();applySpotVisibility()})}
function applySpotVisibility(){let showBuilt=spotListMode!=='own',showOwn=spotListMode!=='built',z=map.getZoom(),zoomOK=z>=9;if(showBuilt&&active.spots&&zoomOK)spotLayer.addTo(map);else if(map.hasLayer(spotLayer))map.removeLayer(spotLayer);if(showOwn&&active.custom&&zoomOK)customLayer.addTo(map);else if(map.hasLayer(customLayer))map.removeLayer(customLayer)}renderList();map.on('zoomend',applySpotVisibility);
function renderCustom(){customLayer.clearLayers();customSpots.forEach((s,i)=>L.marker([s.lat,s.lon],{title:s.name,icon:customIcon(i)}).bindTooltip(`E${i+1} · ${s.name}`).on('click',()=>openSpot(s,true)).addTo(customLayer));renderList()}renderCustom();
