function editCustom(s){openSheet(`<h2>Eigenen Spot</h2><form id="cf" class="formGrid"><label class="span2">Name<input name="name" required value="${s?.name||''}"></label><label class="span2">Notiz<textarea name="note">${s?.note||''}</textarea></label><label>Bewertung<select name="rating"><option>1</option><option>2</option><option selected>3</option><option>4</option><option>5</option></select></label><label>Küste zeigt nach<select name="facing"><option value="0">N</option><option value="90">O</option><option value="180">S</option><option value="270" selected>W</option></select></label><button class="actionBtn primary span2">Speichern & Detail öffnen</button></form>`);$('#cf').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);s.name=f.get('name');s.note=f.get('note');s.rating=+f.get('rating');s.facing=+f.get('facing');saveCustom();renderCustom();openSpot(s,true)}}
