map.on('click',e=>{if(addMode){cancelModes(false);let s={id:'c'+Date.now(),lat:e.latlng.lat,lon:e.latlng.lng,name:'Neuer Spot',note:'',rating:3,facing:Math.round(seaBearing({lat:e.latlng.lat,lon:e.latlng.lng})/45)*45%360};customSpots.push(s);saveCustom();renderCustom();editCustom(s)}else if(homeMode){cancelModes(false);home={lat:e.latlng.lat,lon:e.latlng.lng,name:'Ferienhaus'};localStorage.setItem('gst-home-v6',JSON.stringify(home));renderHome();status('Ferienhaus gespeichert.')}});
function renderHome(){homeLayer.clearLayers();if(home)L.marker([home.lat,home.lon],{icon:L.divIcon({className:'homeIcon',html:'🏠',iconSize:[28,28]})}).bindTooltip(home.name).on('click',()=>googleNav(home.lat,home.lon)).addTo(homeLayer)}renderHome();

function hav(a,b){const R=6371000,p1=a[0]*Math.PI/180,p2=b[0]*Math.PI/180,dp=(b[0]-a[0])*Math.PI/180,dl=(b[1]-a[1])*Math.PI/180;const x=Math.sin(dp/2)**2+Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)**2;return 2*R*Math.asin(Math.sqrt(x))}
function coastDistance(p,coastPts){let min=Infinity;for(const q of coastPts){let d=hav([p.lat,p.lon],q);if(d<min)min=d}return min}
const OVERPASS_ENDPOINTS=['https://overpass-api.de/api/interpreter','https://overpass.kumi.systems/api/interpreter'];
async function overpass(q){let last;for(const ep of OVERPASS_ENDPOINTS){try{return await json(ep+'?data='+encodeURIComponent(q))}catch(e){last=e}}throw last||Error('Overpass unavailable')}
async function parkingQuery(bounds){let bb=`${bounds.s},${bounds.w},${bounds.n},${bounds.e}`;let q=`[out:json][timeout:30];(node[amenity=parking](${bb});way[amenity=parking](${bb});relation[amenity=parking](${bb}););out center;`;return overpass(q)}
const MAX_PARK_COAST_M=800;
let parkingWholeCache=null,parkingLoading=false;
function parseParking(d,anchor=null){let coast=coastMaskPolys.flatMap(poly=>poly.map(g=>[g[0],g[1]]));return(d.elements||[]).filter(x=>x.tags?.amenity==='parking').map(x=>({id:`${x.type}-${x.id}`,lat:x.lat||x.center?.lat,lon:x.lon||x.center?.lon,name:x.tags?.name||'Parkplatz',access:x.tags?.access||'',foot:x.tags?.foot||'',surface:x.tags?.surface||'',capacity:x.tags?.capacity||''})).filter(x=>x.lat&&x.lon&&!['private','no'].includes(x.access)&&x.foot!=='no').map(p=>({...p,coast:coast.length?coastDistance(p,coast):null,spot:anchor?hav(anchor,[p.lat,p.lon]):null})).filter(p=>p.coast!=null&&p.coast<=MAX_PARK_COAST_M).sort((a,b)=>(a.spot??a.coast)-(b.spot??b.coast))}
function parkingMarker(p){let meters=Math.round(p.coast/10)*10,coastTxt=`ca. ${meters} m zum Wasser (Luftlinie)`;let popup=`<b>🅿 ${p.name}</b><br>${coastTxt}<br><small>Nur öffentlich/unkritisch getaggte OSM-Parkplätze innerhalb ${MAX_PARK_COAST_M} m zur Meeresküste. Die tatsächliche Gehroute und Zugänglichkeit bitte vor Ort prüfen.</small><br><button class="miniNav" onclick="window.open('https://www.google.com/maps/dir/?api=1&destination=${p.lat},${p.lon}&travelmode=walking','_blank')">Route öffnen</button>`;return L.marker([p.lat,p.lon],{icon:L.divIcon({className:'parkingIcon',html:'P',iconSize:[25,25]})}).bindTooltip(`${p.name} · ${coastTxt}`).bindPopup(popup)}
async function loadParkingNear(s,showInSheet=false){status('Suche fußläufige Küstenparkplätze…');let dlat=.065,dlon=.11;try{await loadCoastMask();let d=await parkingQuery({s:s.lat-dlat,w:s.lon-dlon,n:s.lat+dlat,e:s.lon+dlon}),arr=parseParking(d,[s.lat,s.lon]).filter(p=>p.spot<6000).slice(0,24);parkingLayer.clearLayers();arr.forEach(p=>parkingLayer.addLayer(parkingMarker(p)));parkingLayer.addTo(map);active.parking=true;if(showInSheet){let box=$('#parkResults');box.innerHTML='<h3>Küstenparkplätze</h3><p class="subtle">Gefiltert auf max. 800 m Luftlinie zur Meeresküste; private/gesperrte Parkplätze werden ausgeschlossen. Gehweg/Zugang bitte vor Ort prüfen.</p>'+(!arr.length?'<p class="subtle">Keine passenden OSM-Parkplätze gefunden.</p>':arr.slice(0,12).map((p,i)=>`<button class="actionBtn parkLink" data-i="${i}">🅿 ${p.name} · ~${Math.round(p.coast)} m Wasser${p.spot!=null?' · '+(p.spot/1000).toFixed(1)+' km Spot':''}</button>`).join(''));box.querySelectorAll('.parkLink').forEach(b=>b.onclick=()=>googleNav(arr[+b.dataset.i].lat,arr[+b.dataset.i].lon))}status(`${arr.length} küstennahe Parkplätze gefunden.`)}catch(e){console.warn(e);status('Parkplatzabruf derzeit nicht verfügbar – bitte später erneut versuchen.')}}
function parkingTiles(){return[{s:56.84,w:17.88,n:57.12,e:19.02},{s:57.10,w:17.88,n:57.40,e:19.04},{s:57.38,w:17.90,n:57.68,e:19.08},{s:57.66,w:18.05,n:57.92,e:19.18},{s:57.88,w:18.30,n:58.13,e:19.52}]}
