function landOverlayGrid(){let LandGrid=L.GridLayer.extend({createTile:function(coords,done){let tile=L.DomUtil.create('canvas','landOverlayTile'),size=this.getTileSize();tile.width=size.x;tile.height=size.y;let ctx=tile.getContext('2d',{alpha:true}),img=new Image();img.crossOrigin='anonymous';img.onload=()=>{try{let origin=L.point(coords.x*size.x,coords.y*size.y),rowStep=2;ctx.fillStyle='#000';for(let y=0;y<size.y;y+=rowStep){let ll=map.unproject(origin.add([size.x/2,y+rowStep/2]),coords.z),cross=coastCrossings(ll.lat);if(cross.length<2)continue;for(let i=0;i+1<cross.length;i+=2){let p1=map.project([ll.lat,cross[i]],coords.z).subtract(origin),p2=map.project([ll.lat,cross[i+1]],coords.z).subtract(origin),x1=Math.max(0,Math.min(size.x,p1.x)),x2=Math.max(0,Math.min(size.x,p2.x));if(x2>x1)ctx.fillRect(x1,y,x2-x1,rowStep+1)}}ctx.globalCompositeOperation='source-in';ctx.drawImage(img,0,0,size.x,size.y);ctx.globalCompositeOperation='source-over'}catch(e){console.warn('Landoverlay',e)}done(null,tile)};img.onerror=()=>done(null,tile);img.src=baseTileUrl(coords);return tile}});return new LandGrid({pane:'landCoverPane',tileSize:256,opacity:1,updateWhenIdle:false,updateWhenZooming:false,keepBuffer:3,noWrap:true,bounds:[[56.70,17.70],[58.30,19.75]],className:'landOverlayGrid'})}
function updateLandCover(){landCoverLayer.clearLayers();if(map.hasLayer(landCoverLayer))map.removeLayer(landCoverLayer);let seaOn=active.current||active.wind||active.temp||active.level||active.wave||active.turbidity;if(!seaOn||!coastSegments.length)return;landOverlayGrid().addTo(landCoverLayer);landCoverLayer.addTo(map)}
