async function refreshConditionStrip(){try{let c=map.getCenter(),r=await live({lat:c.lat,lon:c.lng},true),m=r.m?.hourly,idx=Math.min(timelineIndex,(m?.time?.length||1)-1);let t=m?.sea_surface_temperature?.[idx],w=m?.wave_height?.[idx],l=m?.sea_level_height_msl?.[idx];let a=document.querySelector('#stripTemp'),b=document.querySelector('#stripWave'),d=document.querySelector('#stripLevel');if(a)a.textContent=t==null?'–':`${(+t).toFixed(1)}°`;if(b)b.textContent=w==null?'–':`${(+w).toFixed(1)} m`;if(d)d.textContent=l==null?'–':`${Math.round(+l*100)} cm`;let u=document.querySelector('#stripTurb');if(u)u.textContent=active.turbidity?'TUR':'–'}catch{}}

function denseVectorPoints(kind){let b=map.getBounds(),z=map.getZoom(),step=z>=13?.025:z>=12?.035:z>=11?.050:z>=10?.070:.115,lonStep=step*1.55,s=Math.max(SEA_DOMAIN.s,b.getSouth()),n=Math.min(SEA_DOMAIN.n,b.getNorth()),w=Math.max(SEA_DOMAIN.w,b.getWest()),e=Math.min(SEA_DOMAIN.e,b.getEast()),out=[];for(let lat=s;lat<=n;lat+=step)for(let lon=w;lon<=e;lon+=lonStep)out.push({lat:+lat.toFixed(5),lon:+lon.toFixed(5)});let cap=kind==='wind'?180:210;if(out.length<=cap)return out;let stride=Math.ceil(out.length/cap);return out.filter((_,i)=>i%stride===0).slice(0,cap)}
function nearestVectorFast(lat,lon,samples){let best=[];for(const a of samples){let dx=(lon-a.lon)*Math.cos(lat*Math.PI/180),dy=lat-a.lat,d2=dx*dx+dy*dy;if(d2<1e-8)return{v:a.v,dir:a.dir};if(best.length<7){best.push({a,d2});best.sort((x,y)=>x.d2-y.d2)}else if(d2<best[6].d2){best[6]={a,d2};for(let i=6;i>0&&best[i].d2<best[i-1].d2;i--){let t=best[i];best[i]=best[i-1];best[i-1]=t}}}let su=0,sn=0,sw=0;for(const x of best){let w=1/Math.pow(x.d2,1.18);su+=x.a.u*w;sn+=x.a.n*w;sw+=w}return sw?vdFrom(su/sw,sn/sw):null}
function nearestScalarFast(lat,lon,samples){let best=[];for(const a of samples){let dx=(lon-a.lon)*Math.cos(lat*Math.PI/180),dy=lat-a.lat,d2=dx*dx+dy*dy;if(d2<1e-8)return a.value;if(best.length<7){best.push({a,d2});best.sort((x,y)=>x.d2-y.d2)}else if(d2<best[6].d2){best[6]={a,d2};for(let i=6;i>0&&best[i].d2<best[i-1].d2;i--){let t=best[i];best[i]=best[i-1];best[i-1]=t}}}let sv=0,sw=0;for(const x of best){let w=1/Math.pow(x.d2,1.15);sv+=x.a.value*w;sw+=w}return sw?sv/sw:null}
function eraseLandFromTile(ctx,coords,size){let masks=landMasks(),origin=L.point(coords.x*size.x,coords.y*size.y);ctx.save();ctx.globalCompositeOperation='destination-out';for(const poly of masks){ctx.beginPath();let used=false;for(const p of poly){let pt=map.project(L.latLng(p[0],p[1]),coords.z).subtract(origin);if(!used){ctx.moveTo(pt.x,pt.y);used=true}else ctx.lineTo(pt.x,pt.y)}if(used){ctx.closePath();ctx.fill()}}ctx.restore()}
function scalarGrid(samples,colorFn,vector=false){let ScalarGrid=L.GridLayer.extend({createTile:function(coords){let tile=L.DomUtil.create('canvas','scalarGridTile'),size=this.getTileSize();tile.width=size.x;tile.height=size.y;let ctx=tile.getContext('2d',{alpha:true}),origin=L.point(coords.x*size.x,coords.y*size.y),step=6;ctx.imageSmoothingEnabled=true;for(let y=0;y<size.y;y+=step){for(let x=0;x<size.x;x+=step){let ll=map.unproject(origin.add([x+step/2,y+step/2]),coords.z);if(ll.lat<SEA_DOMAIN.s||ll.lat>SEA_DOMAIN.n||ll.lng<SEA_DOMAIN.w||ll.lng>SEA_DOMAIN.e)continue;let q=vector?nearestVectorFast(ll.lat,ll.lng,samples):nearestScalarFast(ll.lat,ll.lng,samples);if(q==null)continue;ctx.fillStyle=colorFn(vector?q.v:q);ctx.fillRect(x,y,step+1,step+1)}}return tile}});return new ScalarGrid({pane:'seaDataPane',tileSize:256,opacity:.72,updateWhenIdle:false,updateWhenZooming:false,keepBuffer:3,noWrap:true,bounds:[[SEA_DOMAIN.s,SEA_DOMAIN.w],[SEA_DOMAIN.n,SEA_DOMAIN.e]],className:'scalarGrid'})}
function drawScalarBands(samples,layer,colorFn,vector=false){let b=map.getBounds(),s=Math.max(SEA_DOMAIN.s,b.getSouth()),n=Math.min(SEA_DOMAIN.n,b.getNorth()),w=Math.max(SEA_DOMAIN.w,b.getWest()),e=Math.min(SEA_DOMAIN.e,b.getEast()),z=map.getZoom(),rows=z>=12?24:z>=10?20:16,cols=Math.round(rows*Math.max(.8,Math.min(1.8,(e-w)/Math.max(.01,n-s)))),dy=(n-s)/rows,dx=(e-w)/cols;for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){let lat1=s+r*dy,lat2=lat1+dy,lon1=w+c*dx,lon2=lon1+dx,lat=(lat1+lat2)/2,lon=(lon1+lon2)/2,q=vector?nearestVectorFast(lat,lon,samples):nearestScalarFast(lat,lon,samples);if(q==null)continue;L.rectangle([[lat1,lon1],[lat2,lon2]],{pane:'seaDataPane',stroke:false,fill:true,fillColor:colorFn(vector?q.v:q),fillOpacity:.68,interactive:false}).addTo(layer)}}
function drawStaticVectors(samples,layer,kind){for(const p of denseVectorPoints(kind)){let x=idwVector(p.lat,p.lon,samples);if(x)L.marker([p.lat,p.lon],{icon:vectorGlyphIcon(x.dir,x.v,kind),keyboard:false,interactive:false}).addTo(layer)}}
function drawDenseCurrent(samples,layer){drawScalarBands(samples,layer,currentColor,true);drawStaticVectors(samples,layer,'current')}
function windColor(v){if(v<5)return'#dff2f1';if(v<12)return'#b7e4df';if(v<20)return'#80cfbd';if(v<28)return'#46b59c';if(v<38)return'#f0d95b';if(v<50)return'#f49b42';return'#d95545'}
function tempColor(t){if(t<6)return'#275aa8';if(t<9)return'#2c7bb6';if(t<12)return'#73add1';if(t<15)return'#77c7b2';if(t<17)return'#f4d35e';if(t<19)return'#f28e55';return'#d94a3f'}
async function loadVectors(kind){let layer=kind==='wind'?windLayer:currentLayer;layer.clearLayers();active[kind]=true;updateTimeline();if(!map.hasLayer(layer))layer.addTo(map);try{if(kind==='current'){status('Lade Strömungsfeld…');let samples=await fetchCurrentSamples();drawDenseCurrent(samples,layer);updateLandCover();status(`Strömung aktiv · ${samples.length} Datenpunkte · Farbe = Stärke, Pfeil = Richtung.`);return}status('Lade Windfeld…');let samples=await fetchWindSamples();drawScalarBands(samples,layer,windColor,true);drawStaticVectors(samples,layer,'wind');updateLandCover();status(`Wind aktiv · ${samples.length} Datenpunkte · statische Pfeile.`)}catch(e){console.warn(e);status(kind==='wind'?'Winddaten derzeit nicht verfügbar.':'Strömungsdaten derzeit nicht verfügbar.')}}
async function loadTemp(){tempLayer.clearLayers();active.temp=true;updateTimeline();status('Lade Wassertemperatur…');if(!map.hasLayer(tempLayer))tempLayer.addTo(map);try{let samples=await fetchTempSamples();drawScalarBands(samples,tempLayer,tempColor,false);updateLandCover();status(`Wassertemperatur aktiv · ${samples.length} Datenpunkte.`)}catch(e){console.warn(e);status('Wassertemperatur derzeit nicht verfügbar.')}}
function currentContext(s,samples){let q=idwVector(s.lat,s.lon,samples);if(!q)return null;let vals=[];let offs=[[0,0],[.006,0],[-.006,0],[0,.010],[0,-.010]];for(const [dy,dx] of offs){let x=idwVector(s.lat+dy,s.lon+dx,samples);if(x)vals.push(x.v)}return{...q,edge:vals.length?Math.max(...vals)-Math.min(...vals):0}}
let shore50Loaded=false;
function simplifyCoastGeom(geom,minMeters=85){if(geom.length<3)return geom;let out=[geom[0]],last=[geom[0].lat,geom[0].lon];for(let i=1;i<geom.length-1;i++){let cur=[geom[i].lat,geom[i].lon];if(hav(last,cur)>=minMeters){out.push(geom[i]);last=cur}}out.push(geom[geom.length-1]);return out}
function offsetCoastWay(geom){let center=[57.47,18.55],simple=simplifyCoastGeom(geom,90),out=[];for(let i=0;i<simple.length;i++){let p=simple[i],a=simple[Math.max(0,i-1)],b=simple[Math.min(simple.length-1,i+1)],tan=bearing([a.lat,a.lon],[b.lat,b.lon]),c1=destination(p.lat,p.lon,tan+90,50),c2=destination(p.lat,p.lon,tan-90,50),d1=hav(center,c1),d2=hav(center,c2);out.push(d1>d2?c1:c2)}return out}
function updateShore50Visibility(){if(!active.bathy||map.getZoom()<13){if(map.hasLayer(shore50Layer))map.removeLayer(shore50Layer);return}if(shore50Loaded&&!map.hasLayer(shore50Layer))shore50Layer.addTo(map)}
async function loadShore50(){if(shore50Loaded){updateShore50Visibility();return}shore50Layer.clearLayers();status('Lade geglättete ca. 50-m-Küstenlinie…');let q='[out:json][timeout:45];way[natural=coastline](56.84,17.88,58.13,19.52);out geom;';try{let d=await overpass(q);for(const w of d.elements||[]){let g=w.geometry||[];if(g.length<3)continue;let total=0;for(let i=1;i<g.length;i++)total+=hav([g[i-1].lat,g[i-1].lon],[g[i].lat,g[i].lon]);if(total<700)continue;let line=offsetCoastWay(g);L.polyline(line,{color:'#ffffff',weight:4,opacity:.82,interactive:false,smoothFactor:2}).addTo(shore50Layer);L.polyline(line,{color:'#173e50',weight:1.6,opacity:.9,dashArray:'10 7',interactive:false,smoothFactor:2}).addTo(shore50Layer)}shore50Loaded=true;updateShore50Visibility();status(map.getZoom()>=13?'Wassertiefe aktiv · geglättete 50-m-Orientierungslinie sichtbar.':'Wassertiefe aktiv · 50-m-Linie erscheint ab Zoomstufe 13.')}catch(e){console.warn(e);status('Wassertiefe aktiv · 50-m-Küstenlinie konnte nicht geladen werden.')}}
map.on('zoomend',updateShore50Visibility);
function setLayer(key,on){active[key]=on;let layer={spots:spotLayer,custom:customLayer,home:homeLayer,protected:protectedLayer,parking:parkingLayer,bathy,wind:windLayer,current:currentLayer,temp:tempLayer,turbidity:turbidityLayer,level:seaLevelLayer,wave:waveLayer}[key];if(!on){if(map.hasLayer(layer))map.removeLayer(layer);if(key==='bathy'&&map.hasLayer(shore50Layer))map.removeLayer(shore50Layer)}else if(key==='wind')loadVectors('wind');else if(key==='current')loadVectors('current');else if(key==='temp')loadTemp();else if(key==='turbidity')loadTurbidity();else if(key==='level')loadSeaLevel();else if(key==='wave')loadWave();else if(key==='parking')loadCoastalParkingGotland();else{layer.addTo(map);if(key==='bathy')loadShore50()}if(key==='spots'||key==='custom')applySpotVisibility();updateLandCover();renderLegends();updateTimeline();refreshConditionStrip()}
function switchHtml(key,label){return `<div class="layerRow ${active[key]?'on':''}"><span>${label}</span><label class="switch"><input type="checkbox" data-layer="${key}" ${active[key]?'checked':''}><span class="slider"></span></label></div>`}
function layerSheet(){openSheet(`<h2>Karten-Layer</h2><p class="subtle">In der Spotliste kannst du zwischen Alle / Spots / Eigene wählen. Voreinstellung: Alle.</p><div class="layerList">${switchHtml('spots','🎣 Angelspots')}${switchHtml('custom','📌 Eigene Spots')}${switchHtml('parking','🅿 Küstenparkplätze · ≤ 800 m zum Wasser')}${switchHtml('protected','⚠ Schutzgebiete')}${switchHtml('current','🌊 Strömung – statisch')}${switchHtml('wind','💨 Wind – statisch')}${switchHtml('temp','🌡 Wassertemperatur')}${switchHtml('turbidity','◌ Trübung · Copernicus Sentinel-2')}${switchHtml('wave','🌊 Wellenhöhe')}${switchHtml('level','↕ Wasserstand')}${switchHtml('bathy','〰 Wassertiefen')}${switchHtml('home','🏠 Ferienhaus')}</div><p class="depthNote">Zeitabhängige Layer nutzen gemeinsam die Zeitachse unten auf der Karte. Wind und Strömung werden ruhig und statisch dargestellt: Farbe = Stärke, Pfeil = Richtung. Die Datenfläche wird vollständig gerendert; darüber liegt eine separate, präzise Küsten-Landebene. Fällt diese aus, bleiben die Daten trotzdem sichtbar. Wassertemperatur ist eine geglättete Fläche statt Kreisen. Trübung nutzt Copernicus Marine Sentinel-2 (TUR/FNU). Eine einzige Darstellung wird gezeigt; Quellen werden intern automatisch gewählt bzw. abgeglichen. Die ca. 50-m-Küstenlinie erscheint erst beim stärkeren Hineinzoomen.</p>`);document.querySelectorAll('[data-layer]').forEach(x=>x.onchange=e=>{setLayer(e.target.dataset.layer,e.target.checked);e.target.closest('.layerRow').classList.toggle('on',e.target.checked)})}
function renderLegends(){let b=$('#mapLegends'),html='';if(active.current)html+=`<div class="mapLegend currentLegend collapsibleLegend"><button class="legendHead"><b>Strömung · kn</b><span>⌄</span></button><div class="legendBody"><div class="currentLegendRows"><div class="currentLegendRow"><span class="currentLegendDot"></span><span>0–0,08 · nahezu still</span></div><div class="currentLegendRow"><span class="currentLegendSwatch" style="background:#d9efd5"></span><span>0,08–0,25</span></div><div class="currentLegendRow"><span class="currentLegendSwatch" style="background:#91cf86"></span><span>0,50–0,85</span></div><div class="currentLegendRow"><span class="currentLegendSwatch" style="background:#fff04a"></span><span>1,20–1,60</span></div><div class="currentLegendRow"><span class="currentLegendSwatch" style="background:#ffb23d"></span><span>1,60–2,10</span></div><div class="currentLegendRow"><span class="currentLegendSwatch" style="background:#d9362b"></span><span>&gt;2,50</span></div></div><small>Farbe = Stärke · Pfeil = Richtung</small></div></div>`;if(active.wind)html+=`<div class="mapLegend collapsibleLegend"><button class="legendHead"><b>Wind · km/h</b><span>⌄</span></button><div class="legendBody"><div class="grad windGrad"></div><div class="ticks"><span>0</span><span>12</span><span>20</span><span>28</span><span>38</span><span>50+</span></div><small>Farbe = Stärke · Pfeil = Windrichtung</small></div></div>`;if(active.temp)html+=`<div class="mapLegend collapsibleLegend"><button class="legendHead"><b>Wasser · °C</b><span>⌄</span></button><div class="legendBody"><div class="grad tempGrad"></div><div class="ticks"><span>6</span><span>9</span><span>12</span><span>15</span><span>17</span><span>19+</span></div></div></div>`;if(active.turbidity)html+=`<div class="mapLegend collapsibleLegend"><button class="legendHead"><b>Trübung · FNU</b><span>⌄</span></button><div class="legendBody"><div class="grad turbGrad"></div><div class="ticks"><span>klar</span><span>leicht</span><span>mittel</span><span>stark</span></div><small>Copernicus Marine · Sentinel-2 · Satellitenbeobachtung</small></div></div>`;if(active.wave)html+=`<div class="mapLegend collapsibleLegend"><button class="legendHead"><b>Welle · m</b><span>⌄</span></button></div>`;if(active.level)html+=`<div class="mapLegend collapsibleLegend"><button class="legendHead"><b>Wasserstand · m</b><span>⌄</span></button></div>`;if(active.bathy)html+=`<div class="mapLegend collapsibleLegend"><button class="legendHead"><b>Wassertiefe · m</b><span>⌄</span></button><div class="legendBody"><div class="grad depthGrad"></div><div class="ticks"><span>0</span><span>5</span><span>10</span><span>20</span><span>50</span><span>100+</span></div><small>Farben visuell an die EMODnet-Darstellung angepasst · gestrichelt: ca. 50 m ab Zoom 13</small></div></div>`;b.innerHTML=html;b.querySelectorAll('.legendHead').forEach(btn=>btn.onclick=()=>btn.closest('.collapsibleLegend').classList.toggle('legendOpen'));syncQuickLayers()}

function syncQuickLayers(){document.querySelectorAll('#quickLayers [data-quick]').forEach(btn=>{let k=btn.dataset.quick,on=k==='base'?(!active.bathy&&!active.temp&&!active.current&&!active.wind&&!active.turbidity):!!active[k];btn.classList.toggle('active',on)})}
function setQuickLayer(key){cancelModes(false);if(key==='base'){['bathy','temp','current','wind','turbidity'].forEach(k=>{if(active[k])setLayer(k,false)})}else{['bathy','temp','current','wind','turbidity'].forEach(k=>{if(k!==key&&active[k])setLayer(k,false)});setLayer(key,!active[key])}syncQuickLayers()}
document.querySelectorAll('#quickLayers [data-quick]').forEach(btn=>btn.onclick=()=>setQuickLayer(btn.dataset.quick));
function initTimeline(){let now=new Date();now.setMinutes(0,0,0);timelineHours=Array.from({length:48},(_,i)=>new Date(now.getTime()+i*3600000));let range=$('#timeRange'),timeline=$('#timeline'),play=$('#playTime'),playTimer=null;range.max=47;range.value=0;range.oninput=e=>{timelineIndex=+e.target.value;refreshTimed()};$('#nextTime').onclick=()=>stepTimeline(1);play.onclick=()=>{if(playTimer){clearInterval(playTimer);playTimer=null;play.textContent='▶';return}play.textContent='Ⅱ';playTimer=setInterval(()=>{if(timelineIndex>=47){clearInterval(playTimer);playTimer=null;play.textContent='▶';return}stepTimeline(1)},1400)};if(window.L?.DomEvent){L.DomEvent.disableClickPropagation(timeline);L.DomEvent.disableScrollPropagation(timeline)}['pointerdown','pointermove','pointerup','touchstart','touchmove','touchend','mousedown','mousemove','mouseup','click'].forEach(type=>range.addEventListener(type,e=>e.stopPropagation(),{passive:true}));updateTimeline();refreshConditionStrip()}
function stepTimeline(delta){timelineIndex=Math.max(0,Math.min(47,timelineIndex+delta));$('#timeRange').value=timelineIndex;refreshTimed()}
let refreshTimer;function refreshTimed(){updateTimeline();clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>{if(active.current)loadVectors('current');if(active.wind)loadVectors('wind');if(active.temp)loadTemp();if(active.level)loadSeaLevel();if(active.wave)loadWave();refreshConditionStrip()},250)}
function updateTimeline(){let show=active.current||active.wind||active.temp||active.level||active.wave;$('#timeline').classList.toggle('hidden',!show);document.body.classList.toggle('timelineVisible',show);let stripShow=show||active.turbidity;$('#conditionStrip').classList.toggle('hidden',!stripShow);let d=timelineHours[timelineIndex];if(d)$('#timeLabel').textContent=d.toLocaleString('de-DE',{weekday:'short',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).replace(',', ' ·')}

// Schutzgebiete: offizielle Geometrien aus Svenska Fiskeregler (Länsstyrelserna/HaV).
// Die Kartenanzeige ist eine Orientierungshilfe; rechtlich maßgeblich bleibt die veröffentlichte Vorschrift.
const protectionNames=['Själsö','Kolenskvarn','Lummelunda','Lickershamn','Ihre','Vaste','Kiosk','Vitärt','Välles','Arån','Hylu','Hultungs','Bång','Vägume','Vike','Gothem','Storsund','Djupån','Nygårds','Histilles','Halsegårda','Hugreif','Gartarve','Bane','Svajde','Lavas','Tuten','Närk','Kvarne','Snoder','Varbos','Robbjän','Västergarn','Kopparvik'];
function norm(x){return String(x||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function isSeaTroutProtection(props){let text=norm([props?.NAMN,props?.REF_HVMFS,props?.REF_BILAGA].join(' '));return text.includes('2023:11')||protectionNames.some(n=>text.includes(norm(n)))}
async function loadOfficialProtections(){protectedLayer.clearLayers();status('Lade amtliche Schutzgebiete…');let params=new URLSearchParams({where:'1=1',geometry:'17.75,56.80,19.55,58.12',geometryType:'esriGeometryEnvelope',inSR:'4326',spatialRel:'esriSpatialRelIntersects',outFields:'NAMN,REF_HVMFS,REF_BILAGA,REF_PARAGR,REF_KAPITE,REF_ID',returnGeometry:'true',outSR:'4326',f:'geojson'});try{let data=await json(FISH_GIS+'?'+params),features=(data.features||[]).filter(f=>isSeaTroutProtection(f.properties)).filter(f=>{let c=[];function walk(x){if(Array.isArray(x)&&typeof x[0]==='number')c.push(x);else if(Array.isArray(x))x.forEach(walk)}walk(f.geometry?.coordinates);if(!c.length)return false;let xs=c.map(x=>x[0]),ys=c.map(x=>x[1]),dw=Math.max(...xs)-Math.min(...xs),dh=Math.max(...ys)-Math.min(...ys),cx=(Math.max(...xs)+Math.min(...xs))/2,cy=(Math.max(...ys)+Math.min(...ys))/2;return cx>17.8&&cx<19.5&&cy>56.85&&cy<58.12&&dw<.48&&dh<.48});let seenProt=new Set();features=features.filter(f=>{let p=f.properties||{},k=p.REF_ID||[p.NAMN,p.REF_HVMFS,p.REF_BILAGA].join('|');if(seenProt.has(k))return false;seenProt.add(k);return true});officialProtectionFeatures=features;L.geoJSON({type:'FeatureCollection',features},{style:{color:'#a51f2d',weight:2,fillColor:'#e05260',fillOpacity:.28,dashArray:'6 4'},onEachFeature:(f,l)=>{let n=f.properties?.NAMN||'Schutzgebiet';l.bindPopup(`<b>${n}</b><br>Schutzgebiet aus Svenska Fiskeregler.<br>Meerforellen-Mündungsbereiche auf Gotland: Angelverbot 1. Sep.–31. Jan.<br><small>Kartengeometrie dient der Orientierung; rechtlich maßgeblich ist die Vorschrift.</small><br><a href="${RULES}" target="_blank">Länsstyrelsen</a> · <a href="${HVMFS}" target="_blank">HVMFS 2023:11</a>`)}}).addTo(protectedLayer);if(active.protected&&!map.hasLayer(protectedLayer))protectedLayer.addTo(map);status(`${features.length} amtliche Schutzflächen geladen.`)}catch(e){status('Amtliche Schutzflächen konnten nicht geladen werden.');console.warn(e)}}
function featureContainsPoint(f,lat,lon){let g=f.geometry;if(!g)return false;let polys=g.type==='Polygon'?[g.coordinates]:g.type==='MultiPolygon'?g.coordinates:[];return polys.some(poly=>poly.some((ring,i)=>i===0&&inPoly(lat,lon,ring.map(c=>[c[1],c[0]]))))}
function pointInProtection(lat,lon){return officialProtectionFeatures.some(f=>featureContainsPoint(f,lat,lon))}
loadOfficialProtections();

async function today(){cancelModes(false);let box=$('#ranking');box.classList.remove('hidden');box.innerHTML='<b>☀ Beste Spots jetzt</b><p>Lade Wind, Welle und Strömungsanalyse…</p>';let out=[],samples=null;try{samples=await fetchCurrentSamples()}catch{}for(let s of spots){try{let r=await live(s),ctx=samples?currentContext(s,samples):null,d=scoreDetailed(r.w?.current,r.m?.current,s,ctx);out.push({s,sc:d.score,reasons:d.reasons})}catch{}}out.sort((a,b)=>b.sc-a.sc);box.innerHTML='<b>☀ Beste Spots jetzt</b><div class="subtle">Bewertet u. a. Wind zur Küste, Welle, SST, Strömungsstärke/-richtung und Strömungskante.</div>'+out.slice(0,5).map(x=>`<div class="rankRow rankDetailed" data-id="${x.s.id}"><b>${x.s.id}</b><span>${x.s.name}<small>${x.reasons.slice(0,3).join(' · ')||'Bedingungen gemischt'}</small></span><b>${x.sc}/100</b></div>`).join('');box.querySelectorAll('.rankRow').forEach(r=>r.onclick=()=>openSpot(spots.find(s=>s.id==r.dataset.id)))}
function moreSheet(){openSheet(`<h2>Mehr</h2><div class="actions"><button id="rules" class="actionBtn">⚠ Regeln & Schonzeit</button><button id="parkall" class="actionBtn">🅿 Parkplätze</button><button id="backup" class="actionBtn">⇩ Backup</button><button id="gpswarn" class="actionBtn">📍 GPS-Warnung</button><button id="theme" class="actionBtn">🎨 Erscheinungsbild</button><button id="sources" class="actionBtn">ⓘ Quellen & Lizenzen</button></div><div class="officialBox"><b>Meerforellen-Schutzbereiche:</b> Laut Länsstyrelsen gibt es 25 Schutzbereiche an 34 Gewässern. In den Mündungsbereichen gilt 1. September–31. Januar Angelverbot. Die App verwendet keine geschätzten Kreise.</div><p class="subtle">Die Schutzflächen werden live aus dem offiziellen Kartendienst Svenska Fiskeregler geladen. Die Kartendarstellung dient der Orientierung; rechtlich maßgeblich bleibt die Vorschrift.</p>`);$('#rules').onclick=()=>window.open(RULES,'_blank');$('#parkall').onclick=()=>{loadCoastalParkingGotland();closeSheet()};$('#backup').onclick=backup;$('#gpswarn').onclick=enableWatch;$('#theme').onclick=themeSheet;$('#sources').onclick=sourcesSheet}

function applyTheme(v){let t=v==='auto'?(matchMedia('(prefers-color-scheme:dark)').matches?'marine':'light'):v;document.body.dataset.theme=t;localStorage.setItem('gst-theme-v6113',v);setTimeout(updateLandCover,0)}
function themeSheet(){let cur=localStorage.getItem('gst-theme-v6113')||'marine';openSheet(`<h2>Erscheinungsbild</h2><p class="subtle">Alle Designs haben dieselben Funktionen. Nur Farben und Kontrast ändern sich.</p><div class="themeChoices"><button data-theme="marine" class="themeChoice ${cur==='marine'?'selected':''}"><b>Deep Blue</b><small>Dunkelblau/Petrol · hoher Kartenkontrast</small></button><button data-theme="light" class="themeChoice ${cur==='light'?'selected':''}"><b>Nature Light</b><small>Hell · ruhig · klassischer Kartenlook</small></button><button data-theme="outdoor" class="themeChoice ${cur==='outdoor'?'selected':''}"><b>Outdoor</b><small>Sand/Blau · gedeckte Angler-Optik</small></button><button data-theme="auto" class="themeChoice ${cur==='auto'?'selected':''}"><b>Automatisch</b><small>Richtet sich nach dem Geräte-Design</small></button></div>`);document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{applyTheme(b.dataset.theme);document.querySelectorAll('[data-theme]').forEach(x=>x.classList.toggle('selected',x.dataset.theme===b.dataset.theme))})}
applyTheme(localStorage.getItem('gst-theme-v6113')||'marine');
if(window.matchMedia)matchMedia('(prefers-color-scheme:dark)').addEventListener?.('change',()=>{if((localStorage.getItem('gst-theme-v6113')||'marine')==='auto')applyTheme('auto')});

function sourcesSheet(){openSheet(`<h2>Quellen & Lizenzen</h2><div class="sourceList"><p><b>Basiskarte / Parkplätze</b><br>© OpenStreetMap contributors · ODbL<br><a href="${SOURCES.osm}" target="_blank">Lizenz & Attribution</a></p><p><b>Satellitenbilder</b><br>Esri World Imagery · Attribution wird direkt auf der Kartenebene angezeigt.</p><p><b>Bathymetrie</b><br>EMODnet Bathymetry<br><a href="${SOURCES.emodnet}" target="_blank">Quelle</a></p><p><b>Einheitliche Quellenlogik</b><br>Die App zeigt pro Layer nur eine Darstellung. Open-Meteo Best Match/Marine wählt geeignete Modelle automatisch; Copernicus Marine und DMI dienen je nach Parameter als hochauflösende bzw. beobachtungsbasierte Referenz.</p><p><b>Strömung / Welle / Temperatur / Wasserstand</b><br>Open-Meteo Marine + Copernicus/SMHI Referenz; Wasserstand zusätzlich DMI/CMEMS Beobachtungen als Referenz.<br><a href="${SOURCES.openmeteo}" target="_blank">Open-Meteo</a> · <a href="${SOURCES.copernicus}" target="_blank">Copernicus</a> · <a href="${SOURCES.dmi}" target="_blank">DMI</a></p><p><b>Trübung</b><br>Copernicus Marine High Resolution Ocean Colour, Sentinel-2 MSI, Variable TUR in FNU.<br><a href="${SOURCES.copernicusTurb}" target="_blank">Datensatz</a></p><p><b>Fischereiregeln & Schutzgebiete</b><br>Länsstyrelsen Gotland / Havs- och vattenmyndigheten / Svenska Fiskeregler<br><a href="${RULES}" target="_blank">Regeln</a> · <a href="${HVMFS}" target="_blank">HVMFS 2023:11</a> · <a href="${SOURCES.fiskeregler}" target="_blank">Kartendienst</a></p></div>`)}
function backup(){let blob=new Blob([JSON.stringify({version:'6.1.13',customSpots,home,favs:[...favs]},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='gotland-sea-trout-v6.1.13-backup.json';a.click()}
function enableWatch(){if(!navigator.geolocation){alert('Standort nicht verfügbar.');return}if(watchId!=null){navigator.geolocation.clearWatch(watchId);watchId=null;status('GPS-Warnung beendet.');return}if('Notification'in window&&Notification.permission==='default')Notification.requestPermission();watchId=navigator.geolocation.watchPosition(pos=>{let p=[pos.coords.latitude,pos.coords.longitude];if(!window.meMarker)window.meMarker=L.circleMarker(p,{radius:8,color:'#1565c0',fillOpacity:.8}).addTo(map);else window.meMarker.setLatLng(p);if(pointInProtection(p[0],p[1])&&Date.now()-lastProtectionNotice>10*60*1000){lastProtectionNotice=Date.now();let msg='Achtung: Deine GPS-Position liegt in einer dargestellten amtlichen Schutzfläche. Bitte prüfe die geltende Vorschrift.';status(msg);if('Notification'in window&&Notification.permission==='granted')new Notification('Gotland Sea Trout',{body:msg})}},()=>status('Standort konnte nicht gelesen werden.'),{enableHighAccuracy:true,maximumAge:10000});closeSheet();status('GPS-Warnung aktiv, solange die App geöffnet ist.')}
$('#baseBtn').onclick=()=>{cancelModes(false);satelliteOn=!satelliteOn;if(satelliteOn){map.removeLayer(street);satellite.addTo(map);$('#baseBtn').textContent='▦'}else{map.removeLayer(satellite);street.addTo(map);$('#baseBtn').textContent='▱'}updateLandCover()};
$('#locateBtn').onclick=()=>{cancelModes(false);map.locate({setView:true,maxZoom:15})};map.on('locationfound',e=>{if(!window.meMarker)window.meMarker=L.circleMarker(e.latlng,{radius:8,color:'#1565c0',fillOpacity:.85}).addTo(map);else window.meMarker.setLatLng(e.latlng)});
$('#layersBtn').onclick=layerSheet;$('#todayBtn').onclick=()=>{if(panelCollapsed){panelCollapsed=false;$('#panel').classList.remove('panelCollapsed');$('#panelHandle').textContent='▼ Karte vergrößern'}today()};$('#moreBtn').onclick=moreSheet;
$('#panelHandle').onclick=()=>{panelCollapsed=!panelCollapsed;$('#panel').classList.toggle('panelCollapsed',panelCollapsed);$('#panelHandle').textContent=panelCollapsed?'▲ Menü & Spots':'▼ Karte vergrößern';setTimeout(()=>map.invalidateSize(),220)};

$('#addSpotBtn').onclick=()=>{if(addMode){cancelModes();return}cancelModes(false);addMode=true;$('#addSpotBtn').classList.add('active');$('#addSpotBtn').textContent='✕ Abbrechen';status('Tippe auf der Karte auf deinen neuen Spot.')};
$('#homeBtn').onclick=()=>{if(homeMode){cancelModes();return}cancelModes(false);homeMode=true;$('#homeBtn').classList.add('active');$('#homeBtn').textContent='✕ Abbrechen';status('Tippe auf die Position des Ferienhauses.')};
const qt=$('#quickToggle');qt.onclick=()=>{let open=$('#quickLayers').classList.toggle('quickOpen');qt.setAttribute('aria-expanded',open);qt.textContent=open?'Darstellung ▴':'Darstellung ▾'};document.querySelectorAll('#quickLayers [data-quick]').forEach(b=>b.addEventListener('click',()=>{if(innerWidth<=800){$('#quickLayers').classList.remove('quickOpen');qt.setAttribute('aria-expanded','false');qt.textContent='Darstellung ▾'}}));
initTimeline();renderLegends();
let viewportTimer=null;map.on('moveend zoomend',()=>{clearTimeout(viewportTimer);viewportTimer=setTimeout(()=>{if(active.current)loadVectors('current');if(active.wind)loadVectors('wind');if(active.temp)loadTemp();if(active.level)loadSeaLevel();if(active.wave)loadWave();refreshConditionStrip()},420)});
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js');
